import{_ as t,o as a,c as s,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/schueler/individualdaten-i-uebersicht.png",l="/bilder/schueler/individualdaten-i-status.png",u="/bilder/schueler/individualdaten-i-weitere-funktionen.png",k=JSON.parse('{"title":"Persönliche Daten in Individualdaten I erfassen","description":"","frontmatter":{"title":"Persönliche Daten in Individualdaten I erfassen","source_pageid":241,"source_revision":7023},"headers":[],"relativePath":"schild3/schueler/individualdaten-i-schueler.md","filePath":"schild3/schueler/individualdaten-i-schueler.md"}'),o={name:"schild3/schueler/individualdaten-i-schueler.md"};function h(g,r,c,m,b,p){return a(),s("div",null,[...r[0]||(r[0]=[i('<h1 id="personliche-daten-in-individualdaten-i-erfassen" tabindex="-1">Persönliche Daten in Individualdaten I erfassen <a class="header-anchor" href="#personliche-daten-in-individualdaten-i-erfassen" aria-label="Permalink to &quot;Persönliche Daten in Individualdaten I erfassen&quot;">​</a></h1><p>Erfassen Sie die persönlichen Basis- und Zusatzdaten eines Schulkindes. Die aktuellen Laufbahndaten werden hier teilweise nur angezeigt und im jeweiligen Lernabschnitt bearbeitet.</p><p><a href="/bilder/schueler/individualdaten-i-uebersicht.png"><img src="'+d+'" alt="Die Übersicht der Individualdaten I." loading="lazy"></a></p><p><em>Die Übersicht der Individualdaten I.</em></p><p>Auf dem Karteireiter <strong>Individualdaten I</strong> wird der erste Teil der auf die Person bezogenen Daten gespeichert.</p><p>In der Regel werden die Daten zum Schüler oder der Schülerin eingetragen. Für einige Daten, wie die Meldeadresse, sind offizielle Dokumente vorzuzeigen.</p><p>Im Kopf des Feldes werden Name, Klasse, die interne ID und wann und wer die letzte Änderung am Datensatz durchführte angezeigt.</p><p>Die mit Grau unterlegten Felder im Bereich <em>Aktuelle Laufbahndaten</em> auf der rechten Seite des Feldes bedeuten, dass diese hier in der Übersicht lediglich nur gelesen werden können. Die abschnittsbezogenen Daten werden im Reiter <em>Akt. Halbjahr ➜ Allgemeine Angaben</em> gesetzt. Für das EP-Jahr gelten die unten beschriebenen Besonderheiten.</p>',8),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Die statistisch relevanten Daten werden mit einem Sternchen hinter der Feldbezeichnung gekennzeichnet. Diese Felder müssen zur Erstellung der Statistik korrekt befüllt sein beziehungsweise die korrekte Befüllung entlastet das jährliche Erstellen der Statistik. Hier wurden die Felder über die "),e("em",null,"Verwaltung ➜ Einstellungen"),n(" blau eingefärbt.")])],-1),i('<h2 id="basisdaten" tabindex="-1">Basisdaten <a class="header-anchor" href="#basisdaten" aria-label="Permalink to &quot;Basisdaten&quot;">​</a></h2><p>In diesem Bereich werden die grundsätzlichen Daten zur Person erfasst, wie der <em>Name</em>, <em>Vorname</em> und das <em>Geburtsdatum</em>.</p><p>Über die drei &quot;<strong>...</strong>&quot; neben dem Feld <em>Name</em> kann ein Namenszusatz erfasst werden.</p><p>Die &quot;<strong>+</strong>&quot;-Schaltflächen neben dem <em>Ort</em> und dem <em>Ortsteil</em> öffnen den Katalog, um neue Einträge vorzunehmen. Existierende Einträge der Kataloge können über das Dropdown-Menü bei den Feldern ausgewählt werden.</p><p>Über &quot;<strong>...</strong>&quot; neben der Straße lassen sich zusätzliche Angaben der Adresse vermerken.</p><h2 id="zusatzdaten" tabindex="-1">Zusatzdaten <a class="header-anchor" href="#zusatzdaten" aria-label="Permalink to &quot;Zusatzdaten&quot;">​</a></h2><p>Der <strong>Status</strong> bestimmt, in welchem „Karteikasten“ die Person verwaltet wird. Hier wechseln Sie zum Beispiel von <strong>Neuaufnahme</strong> zu <strong>Aktiv</strong>. Ein erworbener Abschluss allein beendet den aktiven Schulbesuch nicht: Bleibt die Person an der Schule, etwa für die Oberstufe, bleibt sie aktiv. Den Status beim tatsächlichen Verlassen der Schule stimmen Sie mit den Angaben unter <strong>Schulbesuch</strong> ab.</p><p><a href="/bilder/schueler/individualdaten-i-status.png"><img src="'+l+'" alt="Soll der Status geändert werden, müssen im Filter des Schülercontainers sowohl der ursprüngliche wie auch der gewünschte Status enthalten sein." loading="lazy"></a></p><p><em>Soll der Status geändert werden, müssen im Filter des Schülercontainers sowohl der ursprüngliche wie auch der gewünschte Status enthalten sein.</em></p><p>Wenn Sie einen Schüler oder eine Schülerin im Status verändern wollen, so muss der Zielstatus vorher auch mit in der enthalten Filterung sein. Wenn Sie z. B. einen Schüler oder eine Schülerin von der <em>Warteliste</em> auf <em>Aktiv</em> setzen wollen, müssen sowohl die Schülerinnen und Schüler der Warteliste als auch die aktiven angezeigt sein.</p>',10),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Dieses Verhalten können Sie aber unter den dem Menüpunkt "),e("em",null,"Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen"),n(" bei "),e("strong",null,"Status-Wechsel ohne vorherige Filterung auf Ziel-Status ermöglichen"),n(" abschalten.")])],-1),i('<p>Tragen Sie hier die Haupt-Telefonnummern des Schülers oder der Schülerin bei <strong>Telefon</strong> ein. Sie können dann auf dem Karteireiter <em>Erz.-Berechtigte</em> unter &quot;Telefon-Nummern&quot; noch beliebig viele weitere Nummern eintragen.</p><p>Wenn Sie eine Telefonanlage haben, die die automatische Telefonwahl aus Windows heraus unterstützt, dann können Sie diese Nummern mit der rechten Maustaste anklicken und die Nummer direkt an Ihre Telefonanlage leiten lassen.</p><p>Wenn in den <em>Programm-Einstellungen</em> die automatische Übernahme der Telefonnummern zu <em>Erz.-Berechtigte</em> aktiviert ist, fragt das Programm nach, ob bei Änderungen auch die dortigen Nummern angepasst werden sollen.</p><p>Bei einer Neueingabe der Telefonnummer legt SchILD-NRW bei aktivierter Option die Nummern &quot;Festnetz&quot;, &quot;Faxnummer&quot; oder &quot;Mobilnummer&quot; im Reiter <em>Erz.-Berechtigte</em> an. Im Feld &quot;Fax- / Mobilnummer&quot; werden dann die ersten beiden Zeichen ausgewertet. Sollte es sich um &quot;01&quot; handeln, so wird die Nummernart &quot;Mobilnummer&quot; angelegt. Dies kann aber später geändert werden.</p><p>Die Daten wie <em>Fahrschülerart</em> werden über Dropdownmenüs gesetzt, deren Inhalte sich über die jeweiligen <em>Kataloge</em> steuern lassen. Ein eventuelles &quot;<strong>+</strong>&quot; neben der Schaltfläche ruft den passenden Katalog zur Bearbeitung auf.</p><h2 id="weitere-funktionen" tabindex="-1">Weitere Funktionen <a class="header-anchor" href="#weitere-funktionen" aria-label="Permalink to &quot;Weitere Funktionen&quot;">​</a></h2><p><a href="/bilder/schueler/individualdaten-i-weitere-funktionen.png"><img src="'+u+'" alt="Weitere Funktionen in den Indivdualdaten I." loading="lazy"></a></p><p><em>Weitere Funktionen in den Indivdualdaten I.</em></p><p>Hier können über ein Menü einige Funktionen erreicht werden:</p><ul><li><strong>Foto laden</strong></li><li><strong>Foto löschen</strong></li><li><strong>Geschwister suchen</strong> vergleicht Nachname und Adresse. Die Suche kann deshalb Geschwister mit abweichendem Namen oder Wohnort übersehen. Prüfen Sie die Treffer, bevor Sie daraus eine vollständige Geschwisterliste ableiten.</li><li><strong>Zugehörigkeit zu Gruppen zeigen</strong>: Wurden Schüler zu <em>Individuellen Schülergruppen</em> oder <em>Personengruppen</em> hinzugefügt, lassen sich dieser hier anzeigen.</li><li><strong>Vermerke zeigen</strong>: Zeigt alle gesetzten <em>Vermerke</em>. Vermerke werden ansonsten über den Reiter <em>Laufbahninfo</em> angesehen, gesetzt und verändert.</li><li><strong>Telefonnummern zeigen</strong>: Zeigt ein Fenster Telefonnummern von <em>Erz.-Berechtigte</em>.</li></ul><h2 id="aktuelle-laufbahndaten" tabindex="-1">Aktuelle Laufbahndaten <a class="header-anchor" href="#aktuelle-laufbahndaten" aria-label="Permalink to &quot;Aktuelle Laufbahndaten&quot;">​</a></h2><p>Hier werden die Laufbahndaten gezeigt, dies betrifft etwa <em>Klasse</em>, <em>Jahrgang</em> oder die <em>Prüfungsordnung</em>. Diese sind im <em>aktuellen Lernabschnitt</em> hinterlegt und werden üblicherweise über Gruppenprozesse klassenweise gesetzt beziehungsweise automatisch bei einer Versetzung basierend auf der <em>Klassen- und Versetzungstabelle</em> aktualisiert.</p><h2 id="ep-jahr-anzeigen-und-korrigieren" tabindex="-1">EP-Jahr anzeigen und korrigieren <a class="header-anchor" href="#ep-jahr-anzeigen-und-korrigieren" aria-label="Permalink to &quot;EP-Jahr anzeigen und korrigieren&quot;">​</a></h2><p>In der Grundschule werden die Jahrgänge <strong>01 bis 04</strong> geführt. Das <strong>EP-Jahr E1, E2 oder E3</strong> beschreibt zusätzlich die Dauer des Verbleibs in den Jahrgängen <strong>01 und 02</strong>.</p><ul><li><strong>Jahrgang 01 und 02:</strong> Das momentane EP-Jahr wird aus der Schülertabelle angezeigt und ist hier <strong>nicht editierbar</strong>. Die Zuordnung erfolgt <strong>in jedem Halbjahr</strong> unter <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong>.</li><li><strong>Ab Jahrgang 03:</strong> Unter den allgemeinen Angaben des Halbjahres wird kein EP-Jahr mehr eingegeben. Der gespeicherte Wert bleibt hier in <strong>Individualdaten I</strong> sichtbar und kann <strong>für Korrekturen bearbeitet</strong> werden.</li></ul><p>Die vollständige Anleitung finden Sie unter <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">Die Jahre der Schuleingangsphase eintragen</a>.</p><h2 id="weitere-angaben" tabindex="-1">Weitere Angaben <a class="header-anchor" href="#weitere-angaben" aria-label="Permalink to &quot;Weitere Angaben&quot;">​</a></h2><p>Einige dieser Felder wie die Prüfung auf <em>Volljährig</em> werden automatisch gesetzt.</p><p>Andere Felder werden abgefragt und von Hand befüllt. Dies betrifft etwa den Nachweis des <em>Masernschutzes</em> oder ob die <em>Konfession auf Zeugnis</em> gedruckt werden soll.</p><p>Zu beachten ist hier das Feld <em>Keine Auskunft an Dritte</em>. Wurde dieser Haken gesetzt, wird der Schülername im Container auch rot eingefärbt.</p><p>Wurde ein Foto gesetzt, wird dieses unten Rechts angezeigt.</p><p>SchILD-NRW ordnet beim Speichern eine als zweite Staatsangehörigkeit eingetragene deutsche Staatsangehörigkeit automatisch an die erste Stelle. Erfassen Sie die tatsächlichen Staatsangehörigkeiten; Staatsangehörigkeit und Einwanderungsgeschichte sind getrennte Angaben.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Individualdaten_I_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7023.</p>',24)])])}const w=t(o,[["render",h]]);export{k as __pageData,w as default};
